/* Canonical: CoD4x_Client_pub/src/recoil/model.h (MIT; see its LICENSE.md).
 * Server mirror is GENERATED by tools/sync-recoil.py; do not edit the mirror.
 *
 * The recoil contract: the server publishes `sv_recoilContract` (wire grammar below), clients advertise
 * cl_recoilProtocol and the cl_recoilModels bitmask, and both sides run the selected model through the
 * shared simulation in sim.h. To add a model: write recoil/models/<name>.h, give it an ID below and a
 * registry entry, and add its mod profile (docs/recoil-models.md). */
#ifndef COD4X_RECOIL_MODEL_H
#define COD4X_RECOIL_MODEL_H

#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include "engine.h"
#include "models/continuous.h"

/* WIRE_VERSION is the permanent contract grammar; PROTOCOL is the client capability: 2 = the client sends
 * unkicked aim and predicts the server's simulation (docs/authoritative-recoil.md). tools/sync-recoil.py
 * generates the Python tooling's constants from these and the registry. */
enum { RECOIL_WIRE_VERSION = 1, RECOIL_PROTOCOL = 2, RECOIL_MAX_WEAPONS = 16, RECOIL_WIRE_SIZE = 768,
       RECOIL_WEAPON_NAME = 32, RECOIL_MAX_PARAMS = 8, RECOIL_NATIVE = 0, RECOIL_CONTINUOUS = 1 };
#define RECOIL_NATIVE_WIRE "1:0" /* Permanent native contract, including on newer engines. */

/* Model IDs are permanent. Native is never simulated: it stays stock and client-trusted. */
static const recoil_model_t recoil_models[] = {
    {RECOIL_NATIVE, "native", NULL, 0, NULL, NULL, NULL},
    {RECOIL_CONTINUOUS, "continuous", recoil_continuous_params, 3, Recoil_ContinuousValidate, Recoil_ContinuousShot, NULL},
};

typedef struct {
    char weapon[RECOIL_WEAPON_NAME];
    uint32_t param[RECOIL_MAX_PARAMS];
} recoil_weapon_t;
typedef struct recoil_contract_s {
    uint32_t version, model, count;
    recoil_weapon_t weapons[RECOIL_MAX_WEAPONS];
} recoil_contract_t;

static inline unsigned Recoil_RuntimeModels(void)
{
    unsigned mask = 0, i;
    for (i = 0; i < sizeof(recoil_models) / sizeof(*recoil_models); ++i) mask |= 1u << recoil_models[i].id;
    return mask;
}

static inline const recoil_model_t *Recoil_Model(uint32_t id)
{
    unsigned i;
    for (i = 0; i < sizeof(recoil_models) / sizeof(*recoil_models); ++i)
        if (recoil_models[i].id == id) return &recoil_models[i];
    return NULL;
}

/* Every model but native runs the shared simulation. */
static inline int Recoil_Simulated(const recoil_model_t *model)
{
    return model && model->id != RECOIL_NATIVE;
}

/* Canonical decimal only: malformed/overflowing fields never become defaults. */
static inline int Recoil_Number(const char **text, uint32_t *value)
{
    const char *p = *text;
    uint32_t n = 0;
    if (*p < '0' || *p > '9' || (*p == '0' && p[1] >= '0' && p[1] <= '9')) return 0;
    do {
        uint32_t digit = (uint32_t)(*p++ - '0');
        if (n > (UINT32_MAX - digit) / 10) return 0;
        n = n * 10 + digit;
    } while (*p >= '0' && *p <= '9');
    *text = p; *value = n;
    return 1;
}

/* Wire/file: 1:0, or 1:<model>:weapon,p1,...,pN[/weapon,p1,...,pN], with N and bounds from the model's table. */
static inline int Recoil_Decode(const char *text, recoil_contract_t *out)
{
    recoil_contract_t c;
    const recoil_model_t *model;
    unsigned i;
    const char *p = text;
    memset(&c, 0, sizeof(c));
    if (!p || strlen(p) >= RECOIL_WIRE_SIZE || !Recoil_Number(&p, &c.version) ||
        c.version != RECOIL_WIRE_VERSION || *p++ != ':' || !Recoil_Number(&p, &c.model) ||
        !(model = Recoil_Model(c.model))) return 0;
    if (!Recoil_Simulated(model)) {
        if (*p) return 0;
        *out = c; return 1;
    }
    if (*p++ != ':') return 0;
    for (;;) {
        recoil_weapon_t *w;
        unsigned length = 0;
        if (c.count == RECOIL_MAX_WEAPONS) return 0;
        w = &c.weapons[c.count];
        while ((*p >= 'a' && *p <= 'z') || (*p >= '0' && *p <= '9') || *p == '_') {
            if (length == sizeof(w->weapon) - 1) return 0;
            w->weapon[length++] = *p++;
        }
        if (!length) return 0;
        for (i = 0; i < model->param_count; ++i)
            if (*p++ != ',' || !Recoil_Number(&p, &w->param[i]) ||
                w->param[i] < model->params[i].min || w->param[i] > model->params[i].max) return 0;
        if (model->validate && !model->validate(w->param)) return 0;
        for (i = 0; i < c.count; ++i)
            if (!strcmp(c.weapons[i].weapon, w->weapon)) return 0;
        ++c.count;
        if (!*p) break;
        if (*p++ != '/') return 0;
    }
    *out = c;
    return 1;
}

/* Native admits everyone; a simulated model needs an authoritative-capable client that has the model. */
static inline int Recoil_Compatible(const recoil_contract_t *c, uint32_t protocol, uint32_t mask)
{
    return c->model == RECOIL_NATIVE || (protocol >= RECOIL_PROTOCOL &&
        c->model < 32 && (mask & (1u << c->model)) != 0);
}

/* The profile entry for a weapon: its family name plus "_" (ak74u matches ak74u_mp), else NULL (native). */
static inline const uint32_t *Recoil_WeaponParams(const recoil_contract_t *c, const char *weapon_name)
{
    unsigned i;
    if (!weapon_name) return NULL;
    for (i = 0; i < c->count; ++i) {
        const size_t length = strlen(c->weapons[i].weapon);
        if (!strncmp(weapon_name, c->weapons[i].weapon, length) && weapon_name[length] == '_')
            return c->weapons[i].param;
    }
    return NULL;
}

/* Per weapon index: its fixed-point kick data and profile entry, converted once per contract and level. */
typedef struct { recoil_weapon_kick_t kick; const uint32_t *param; int ready; } recoil_weapon_cache_t;

/* hip/ads: WeaponDef's fHipViewKickPitchMin / fAdsViewKickPitchMin (five consecutive floats each). */
static inline const recoil_weapon_kick_t *Recoil_CachedWeapon(recoil_weapon_cache_t *cache,
    const recoil_contract_t *c, const char *name, const float *hip, const float *ads, float hip_reduced_percent,
    float ads_reduced_percent, int fire_msec, const uint32_t **param)
{
    if (!cache->ready) {
        Recoil_WeaponKick(&cache->kick, hip, ads, hip_reduced_percent, ads_reduced_percent, fire_msec);
        cache->param = Recoil_WeaponParams(c, name);
        cache->ready = 1;
    }
    *param = cache->param;
    return &cache->kick;
}

#endif
